[15 Regression][modules] Bogus conflicting friend template declaration
$ cat Test.cpp 

export module m;

template<typename>
class T;

template<typename>
class U
{
  template<typename>
  friend class T;
};

template<typename V>
class T
{
  U<V> x = {};
};

export
template<typename V>
T<V> f(V) { return {}; }

$ cat main.cpp 

import m;

int main()
{
  auto const x = f(1);
}

